[1879512389]={[1]="Splendid Mûrai Feast";[2]="A fortifying feast of local Mûrai dishes, including stuffed eggplant, loaves of foxtail millet bread, eggplant dip, and tender shanks of oryx. The centrepiece of this dish is a massive platter of fried catfish, crispy on the outside and buttery within. Accompanied with your favourite drink, this elaborate feast has something for all. This food creates a feasting table which allows everyone to eat from it for two minutes. Consuming the food from the table provides the benefits of both trail food and cooked food for a long time.";[3]=55;[4]=3;[5]=0;[6]=false;[7]=false;};
[1879512391]={[1]="Rationed Roasted Oryx Shank";[2]="An oryx shank coated with spices and slow roasted over a fire until tender and a touch crispy, served with warm bread. This food can be quickly eaten during battle.";[3]=55;[4]=2;[5]=0;[6]=false;[7]=false;};
